int main() {
    char line[1001];

    while (fgets(line, sizeof(line), stdin)) {
        // Remove newline if present
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') {
            line[len-1] = '\0';
            len--;
        }

        if (len == 0) continue; // Skip empty lines

        // Step 1: Convert each character to 5-bit code and concatenate
        char binary[5001] = ""; // max 1000 chars * 5 bits = 5000 + null
        for (size_t i = 0; i < len; i++) {
            strcat(binary, char_to_code(toupper(line[i])));
        }

        // Step 2: Split into groups of 5 and pad with zeros if needed
        int bin_len = strlen(binary);
        int num_groups = (bin_len + 4) / 5; // ceil division

        // Step 3: Map each group back to character
        for (int i = 0; i < num_groups; i++) {
            char group[6]; // 5 bits + null
            int start = i * 5;
            int remaining = bin_len - start;

            if (remaining >= 5) {
                strncpy(group, binary + start, 5);
                group[5] = '\0';
            } else {
                // Pad with zeros
                int j;
                for (j = 0; j < remaining; j++) {
                    group[j] = binary[start + j];
                }
                for (; j < 5; j++) {
                    group[j] = '0';
                }
                group[5] = '\0';
            }

            printf("%c", code_to_char(group));
        }
        printf("\n");
    }

    return 0;
}

