int charToCode(char c) {
    if (c == ' ') return 0;
    if (c >= 'A' && c <= 'Z') return c - 'A' + 1;
    return 0;
}

char codeToChar(int v) {
    if (v == 0) return ' ';
    if (v >= 1 && v <= 26) return 'A' + v - 1;
    // values 27-31?
    return '?';
}

int main() {
    char line[10000];
    while (fgets(line, sizeof(line), stdin)) {
        // Remove newline
        int len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
            line[--len] = 0;
        }

        // Build bit string
        char bits[100000];
        int blen = 0;
        for (int i = 0; i < len; i++) {
            int code = charToCode(line[i]);
            for (int b = 4; b >= 0; b--) {
                bits[blen++] = ((code >> b) & 1) ? '1' : '0';
            }
        }

        // Pad to multiple of 5
        while (blen % 5 != 0) bits[blen++] = '0';

        // Convert groups of 5 back to characters
        for (int i = 0; i < blen; i += 5) {
            int val = 0;
            for (int b = 0; b < 5; b++) {
                val = val * 2 + (bits[i+b] - '0');
            }
            printf("%c", codeToChar(val));
        }
        printf("\n");
    }
    return 0;
}

