        for (char c : line) {
            int val;
            if (c == ' ') val = 0;
            else if (c >= 'A' && c <= 'Z') val = c - 'A' + 1;
            else if (c >= 'a' && c <= 'z') val = c - 'a' + 1;
            else continue;

            for (int i = 4; i >= 0; i--) {
                bits += ((val >> i) & 1) ? '1' : '0';
            }
        }

        string result = "";
        for (int i = 0; i + 5 <= (int)bits.size(); i += 5) {
            string group = bits.substr(i, 5);
            int val = 0;
            for (char b : group) val = val * 2 + (b - '0');
            if (val == 0) result += ' ';
            else if (val >= 1 && val <= 26) result += (char)('A' + val - 1);
        }

        cout << result << "\n";
    }
    return 0;
