public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Build encoding: A-Z -> 1-26 as 5-bit binary, space -> 00000
        Map<Character, String> encode = new HashMap<>();
        for (int i = 0; i < 26; i++) {
            char c = (char)('A' + i);
            encode.put(c, String.format("%05d", Integer.parseInt(Integer.toBinaryString(i + 1))));
        }
        encode.put(' ', "00000");

        // Build decoding: 5-bit binary string -> character
        Map<String, Character> decode = new HashMap<>();
        for (int i = 0; i < 26; i++) {
            char c = (char)('A' + i);
            decode.put(String.format("%05d", Integer.parseInt(Integer.toBinaryString(i + 1))), c);
        }
        decode.put("00000", ' ');

        while (sc.hasNextLine()) {
            String line = sc.nextLine();
            if (line.equals("0")) break;

            StringBuilder bits = new StringBuilder();
            for (char c : line.toCharArray()) {
                bits.append(encode.get(c));
            }

            // Pad to multiple of 5
            while (bits.length() % 5 != 0) {
                bits.append('0');
            }

            StringBuilder result = new StringBuilder();
            for (int i = 0; i < bits.length(); i += 5) {
                String group = bits.substring(i, i + 5);
                result.append(decode.get(group));
            }

            System.out.println(result.toString());
        }
    }
